// Turns skills/<name>/SKILL.md into mcp/skills.generated.ts, so the MCP server can offer the same instructions as prompts
// (for GPT and any client without skills support). The SKILL.md files stay the single source of truth.
// Run `npm run build:skills` after editing one; a test fails if the generated file is out of date.
import { readdirSync, readFileSync, writeFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import path from 'node:path';

const root = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

/** Files that travel with a skill (templates, assets), by path inside the skill's folder, text only. */
function extraFiles(folder, rel = '') {
  const out = {};
  for (const e of readdirSync(path.join(folder, rel), { withFileTypes: true }).sort((a, b) => a.name.localeCompare(b.name))) {
    const r = rel ? `${rel}/${e.name}` : e.name;
    if (e.isDirectory()) Object.assign(out, extraFiles(folder, r));
    else if (r !== 'SKILL.md') out[r] = readFileSync(path.join(folder, r), 'utf8').replace(/\r\n/g, '\n');
  }
  return out;
}

export function skillsSource(dir = path.join(root, 'skills')) {
  const skills = readdirSync(dir, { withFileTypes: true })
    .filter((e) => e.isDirectory())
    .map((e) => e.name)
    .sort()
    .map((folder) => {
      const text = readFileSync(path.join(dir, folder, 'SKILL.md'), 'utf8').replace(/\r\n/g, '\n');
      const m = /^---\n([\s\S]*?)\n---\n+([\s\S]*)$/.exec(text);
      if (!m) throw new Error(`${folder}/SKILL.md has no front matter`);
      const field = (key) => {
        const v = new RegExp(`^${key}:\\s*(.+)$`, 'm').exec(m[1])?.[1].trim();
        if (!v) throw new Error(`${folder}/SKILL.md has no ${key}`);
        return v.startsWith('"') ? JSON.parse(v) : v;
      };
      const body = m[2].trim();
      // A review skill (an editing pass) signs its notes with a tag and says which: Use `skill: "…"`. An authoring skill has no tag; its title is its heading.
      const noteTag = /Use `skill: "([^"]+)"`/.exec(body)?.[1];
      const title = /^#\s+(.+?)(?:\s+\(Cadrel[^)]*\))?\s*$/m.exec(body)?.[1];
      if (!noteTag && !title) throw new Error(`${folder}/SKILL.md needs a "# Title" heading, or Use \`skill: "…"\` if it leaves notes.`);
      return {
        id: field('name').replace(/^cadrel-/, '').replace(/-/g, '_'),
        name: field('name'),
        description: field('description'),
        kind: noteTag ? 'review' : 'author',
        tag: noteTag ?? title,
        body,
        markdown: text,
        files: extraFiles(path.join(dir, folder)),
      };
    });
  return `// Generated by scripts/skills.mjs from skills/*/SKILL.md. Do not edit; run \`npm run build:skills\`.\nexport const SKILLS: { id: string; name: string; description: string; kind: 'review' | 'author'; tag: string; body: string; markdown: string; files: Record<string, string> }[] = ${JSON.stringify(skills, null, 2)};\n`;
}

export function writeSkills() {
  writeFileSync(path.join(root, 'mcp', 'skills.generated.ts'), skillsSource());
}

if (process.argv[1] === fileURLToPath(import.meta.url)) writeSkills();
